const raw = $input.first().json.body ?? $input.first().json;
const missing = [];
const issues = [];
function text(name) {
  const value = raw[name];
  if (value === undefined || value === null || String(value).trim() === '') {
    missing.push(name);
    return null;
  }
  return String(value).trim();
}
function integer(name, minimum, maximum) {
  const value = text(name);
  if (value === null) return null;
  const number = Number(value);
  if (!Number.isInteger(number) || number < minimum || number > maximum) {
    issues.push(name + ' must be an integer from ' + minimum + ' to ' + maximum);
    return null;
  }
  return number;
}
const brief = text('brief');
if (brief && (brief.length < 10 || brief.length > 4000)) issues.push('brief must contain 10 to 4000 characters');
const production_date = text('production_date');
if (production_date) {
  const parsedDate = new Date(production_date + 'T00:00:00Z');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(production_date) || !Number.isFinite(parsedDate.getTime()) || parsedDate.toISOString().slice(0, 10) !== production_date) {
    issues.push('production_date must be a valid ISO date');
  } else {
    const today = new Date($now.toISODate() + 'T00:00:00Z');
    const daysAhead = (parsedDate.getTime() - today.getTime()) / 86400000;
    if (daysAhead < 0 || daysAhead > 366) issues.push('production_date must be today or within the next 366 days');
  }
}
const duration_hours = integer('duration_hours', 1, 8);
const camera_count = integer('camera_count', 1, 3);
const editing_hours = integer('editing_hours', 0, 8);
const audio = text('include_audio');
let include_audio = null;
if (audio !== null) {
  if (audio === 'true') include_audio = true;
  else if (audio === 'false') include_audio = false;
  else issues.push('include_audio must be true or false');
}
const budgetValue = text('budget_sar');
const budget_sar = budgetValue === null ? null : Number(budgetValue);
if (budgetValue !== null && (!Number.isFinite(budget_sar) || budget_sar <= 0 || budget_sar > 1000000)) {
  issues.push('budget_sar must be a positive amount up to 1000000 SAR');
}
return [{ json: {
  request_id: /^job_[a-f0-9]{32}$/.test(raw.request_id ?? '') ? raw.request_id : 'n8n-' + $execution.id,
  brief, production_date, duration_hours, camera_count, include_audio, editing_hours, budget_sar,
  status: missing.length || issues.length ? 'needs_info' : 'ready',
  missing_fields: missing, validation_issues: issues,
  synthetic: true,
}}];

const input = $('Normalize Input').first().json;
const raw = $input.first().json;
function fail(message) {
  return [{ json: { ...input, status: 'error', reason: message, quote_id: null, claimed_total_sar: null, brief_summary: '', missing_fields: [] }}];
}
if (raw.error) return fail('The AI provider or agent failed. Inspect this execution; no order was created.');
if (typeof raw.output !== 'string' || !raw.output.trim() || raw.output.length > 4000) return fail('The agent production plan was missing or invalid.');
// intermediateSteps is produced by the Agent executor for this successful
// attempt. The model's final prose is never parsed for a quote ID or price.
const steps = raw.intermediateSteps;
const sequence = ['catalog', 'availability', 'quote'];
if (!Array.isArray(steps) || steps.length !== sequence.length) return fail('The agent did not complete exactly the required three tools in one attempt.');
const observations = [];
for (let index = 0; index < sequence.length; index++) {
  const step = steps[index];
  if (!step || step.action?.tool !== sequence[index]) return fail('The agent tools were missing or executed in an unexpected order.');
  const argumentsValue = step.action.toolInput;
  if (!argumentsValue || typeof argumentsValue !== 'object' || Array.isArray(argumentsValue) || Object.keys(argumentsValue).length !== 0) return fail('An agent tool attempted to supply parameters; form values must stay fixed.');
  try {
    if (typeof step.observation !== 'string') throw new Error('Observation must be JSON text');
    const observed = JSON.parse(step.observation);
    if (!Array.isArray(observed) || observed.length !== 1 || !observed[0] || typeof observed[0] !== 'object' || Array.isArray(observed[0])) throw new Error('Unexpected tool response shape');
    observations.push(observed[0]);
  } catch { return fail('An actual agent tool observation was malformed. No order was created.'); }
}
const [catalog, availability, quote] = observations;
if (catalog.synthetic !== true || catalog.currency !== 'SAR' || !Array.isArray(catalog.services) || !catalog.services.length) return fail('The catalog tool did not return a valid synthetic service catalog.');
if (availability.synthetic !== true || typeof availability.available !== 'boolean' || availability.production_date !== input.production_date ||
    !availability.requested || ['duration_hours', 'camera_count', 'include_audio'].some(name => availability.requested[name] !== input[name])) return fail('The availability tool response did not match the original request.');
if (typeof quote.quote_id !== 'string' || !/^q_[a-zA-Z0-9_-]+$/.test(quote.quote_id)) return fail('The quote tool did not return a valid backend quote ID.');
if (typeof quote.total_sar !== 'number' || !Number.isFinite(quote.total_sar) || quote.total_sar < 0) return fail('The quote tool did not return a valid numeric estimate.');
const expected = ['request_id', 'brief', 'production_date', 'duration_hours', 'camera_count', 'include_audio', 'editing_hours'];
if (quote.synthetic !== true || quote.currency !== 'SAR' || quote.request_id !== input.request_id || quote.available !== availability.available ||
    !quote.fields || expected.some(name => quote.fields[name] !== input[name])) return fail('The quote tool response did not match the original form.');
return [{ json: { ...input, status: 'quoted', quote_id: quote.quote_id, claimed_total_sar: quote.total_sar,
  brief_summary: raw.output.trim(), missing_fields: [], agent_tool_sequence: sequence }}];

const input = $('Parse Agent Result').first().json;
const response = $input.first().json;
function fail(status, reason) { return [{ json: { ...input, status, reason, policy_allowed: false } }]; }
if (response.error) return fail('error', 'Quote verification API could not be reached. No order was created.');
if (response.statusCode !== 200 || !response.body || response.body.verified !== true) {
  return fail('error', 'Quote verification failed (HTTP ' + String(response.statusCode ?? 'unknown') + '). No order was created.');
}
const quote = response.body.quote;
if (!quote || quote.quote_id !== input.quote_id || quote.currency !== 'SAR' || quote.synthetic !== true) return fail('error', 'The backend quote identity or currency is invalid.');
const expected = ['request_id', 'brief', 'production_date', 'duration_hours', 'camera_count', 'include_audio', 'editing_hours'];
if (!quote.fields || expected.some(name => quote.fields[name] !== input[name])) return fail('error', 'Canonical quote fields do not match the original form. No order was created.');
if (quote.request_id !== input.request_id) return fail('error', 'The quote belongs to a different request.');
if (typeof quote.total_sar !== 'number' || !Number.isFinite(quote.total_sar) || Math.abs(quote.total_sar - input.claimed_total_sar) > 0.005) return fail('error', 'Canonical total does not match the observed tool estimate.');
if (!Array.isArray(quote.line_items) || !quote.line_items.length) return fail('error', 'The backend quote has no line items.');
const lineTotal = quote.line_items.reduce((total, line) => total + Number(line.line_total_sar), 0);
if (!Number.isFinite(lineTotal) || Math.abs(lineTotal - quote.total_sar) > 0.005) return fail('error', 'The backend line items do not reconcile.');
if (quote.available !== true) return fail('rejected', 'Resources unavailable: ' + String(quote.availability_reason ?? 'capacity limit or maintenance day'));
if (quote.total_sar > input.budget_sar) return fail('rejected', 'The verified estimate of ' + quote.total_sar + ' SAR exceeds your ' + input.budget_sar + ' SAR budget.');
return [{ json: { ...input, status: 'awaiting_review', policy_allowed: true, quote,
  verified_total_sar: quote.total_sar, reason: 'A human decision is required before creating a work order.' } }];
